  var BUS3_QUESTION_BANK = [
    { q: 'Why might a business need finance for short-term needs?', options: ['To pay day-to-day expenses such as wages, stock or utility bills', 'To buy a new factory', 'To fund a takeover of another business', 'To pay off a 20-year mortgage on premises'], correct: 0, explain: 'Short-term finance covers everyday operating costs such as wages, stock purchases and bills, helping a business manage its cash flow.', misconception: 'Buying a factory or funding a takeover are long-term needs, typically financed with long-term sources like loans or share capital.', tag: 'Sources of finance' },
    { q: 'Why might a new business need finance to start up?', options: ['To buy premises, equipment and stock before it starts earning revenue', 'Because start-up finance is only used to pay existing staff wages', 'Because all new businesses are given free government finance', 'Because start-up businesses are not allowed to trade without it'], correct: 0, explain: 'A new business typically needs finance to buy premises, equipment, stock and cover initial costs before it begins generating enough revenue to be self-sufficient.', misconception: 'There is no automatic entitlement to free government finance — most businesses raise start-up capital from personal savings, loans or investors.', tag: 'Sources of finance' },
    { q: 'Which of these is an internal source of finance?', options: ['Retained profit', 'A bank loan', 'An overdraft', 'Venture capital'], correct: 0, explain: 'Retained profit is profit kept within the business from previous trading, making it an internal source of finance that doesn’t need to be borrowed.', misconception: 'Bank loans, overdrafts and venture capital all come from outside the business, making them external sources of finance.', tag: 'Sources of finance' },
    { q: 'What is an overdraft?', options: ['A flexible short-term borrowing facility allowing a business to withdraw more than it has in its account, up to an agreed limit', 'A long-term loan repaid over many years', 'Money raised by selling shares to the public', 'Profit kept in the business rather than distributed'], correct: 0, explain: 'An overdraft is an external, short-term source of finance that lets a business spend more than is in its account, up to an agreed limit, useful for managing cash-flow gaps.', misconception: 'This is different from a long-term loan, which is usually repaid over a fixed, longer period rather than used flexibly for short-term needs.', tag: 'Sources of finance' },
    { q: 'What does “trade payables” refer to as a source of finance?', options: ['Delaying payment to suppliers for goods or services already received', 'Money raised by selling shares', 'A loan from a bank', 'Cash kept as retained profit'], correct: 0, explain: 'Trade payables (trade credit) allow a business to receive goods or services now and pay the supplier later, effectively providing short-term finance.', misconception: 'This does not involve raising new money from shares or loans — it is about delaying an existing payment obligation.', tag: 'Sources of finance' },
    { q: 'What is share capital?', options: ['Money raised by a limited company selling shares to investors', 'Money borrowed from a bank that must be repaid with interest', 'Profit kept within the business', 'A short-term overdraft facility'], correct: 0, explain: 'Share capital is finance raised by a limited company selling shares in the business to investors, who become part-owners (shareholders) in return.', misconception: 'Unlike a bank loan, share capital does not have to be repaid with interest — instead, shareholders may receive dividends and a share of ownership.', tag: 'Sources of finance' },
    { q: 'What is venture capital?', options: ['Finance provided by investors to higher-risk, often new or growing businesses, usually in exchange for a share of ownership', 'A guaranteed government grant for any new business', 'Finance that must be repaid within one week', 'Money raised solely from personal savings'], correct: 0, explain: 'Venture capital is finance provided by specialist investors to businesses seen as higher risk, often in exchange for a stake in the company, in return for the potential of high returns.', misconception: 'Venture capital is not a government grant, and it usually involves the investor taking a share of ownership rather than a fixed short repayment period.', tag: 'Sources of finance' },
    { q: 'What is crowdfunding?', options: ['Raising finance by collecting small amounts of money from a large number of people, often via an online platform', 'A single large loan from one bank', 'Finance raised only from a business’s existing shareholders', 'A type of insurance policy'], correct: 0, explain: 'Crowdfunding involves raising money from a large number of individuals, typically online, each contributing a relatively small amount towards a project or business.', misconception: 'Crowdfunding relies on many small contributors rather than a single lender or an existing group of shareholders.', tag: 'Sources of finance' },
    { q: 'Why is cash important to a business, even if it is profitable?', options: ['A business needs cash to pay its day-to-day bills, such as wages and suppliers, regardless of how much profit it has made', 'Cash and profit always mean exactly the same thing', 'Cash is only needed by businesses that are making a loss', 'Profitable businesses never run short of cash'], correct: 0, explain: 'A business needs sufficient cash available to meet its immediate obligations, such as paying wages and suppliers — this is true even for a business that is profitable overall.', misconception: 'Profit and cash are different: a business can be profitable on paper but still run short of cash if money is tied up elsewhere, such as in unpaid customer invoices.', tag: 'Cash-flow forecasting' },
    { q: 'What is the difference between cash and profit?', options: ['Cash is the money actually available to a business; profit is revenue minus costs over a period, which may not match available cash', 'Cash and profit are always the same amount', 'Profit refers only to money in the bank', 'Cash refers only to a business’s total assets'], correct: 0, explain: 'Cash is the actual money a business has available at a point in time, while profit is an accounting measure of revenue minus costs over a trading period — the two figures often differ.', misconception: 'It’s a common error to treat cash and profit as identical; a business can show a profit while having little cash actually available.', tag: 'Cash-flow forecasting' },
    { q: 'A cash-flow forecast shows total cash inflows of $12,000 and total cash outflows of $9,500 for the month. What is the net cash flow?', options: ['$2,500', '$21,500', '$9,500', '$12,000'], correct: 0, explain: 'Net cash flow = cash inflows − cash outflows = $12,000 − $9,500 = $2,500.', misconception: 'A common mistake is adding the two figures together instead of subtracting outflows from inflows.', tag: 'Cash-flow forecasting' },
    { q: 'If the opening cash balance is $3,000 and the net cash flow for the month is $1,200, what is the closing cash balance?', options: ['$4,200', '$1,800', '$3,000', '$1,200'], correct: 0, explain: 'Closing balance = opening balance + net cash flow = $3,000 + $1,200 = $4,200.', misconception: 'The closing balance must include the opening balance carried forward, not just the net cash flow for the period alone.', tag: 'Cash-flow forecasting' },
    { q: 'What does it mean if a cash-flow forecast shows a cash shortage in a particular month?', options: ['Cash outflows are forecast to exceed cash inflows, meaning the business may not have enough cash available', 'The business is forecast to make a loss that month', 'The business will automatically become insolvent', 'Sales are forecast to fall to zero'], correct: 0, explain: 'A cash shortage means outflows are expected to exceed inflows in that period, so the business may need to arrange extra finance, such as an overdraft, to cover the gap.', misconception: 'A cash shortage is not the same as making a loss — it is about the timing of cash moving in and out, not overall profitability.', tag: 'Cash-flow forecasting' },
    { q: 'Which action could a business take in response to a forecast cash-flow shortage?', options: ['Arrange an overdraft, delay non-essential payments, or chase customer payments more quickly', 'Immediately increase all staff wages', 'Stop recording any further transactions', 'Ignore the forecast, as forecasts are always inaccurate'], correct: 0, explain: 'A business facing a forecast cash shortage could arrange short-term finance such as an overdraft, delay some payments, or speed up money owed by customers.', misconception: 'Increasing wages would worsen a cash shortage, and ignoring a forecast defeats the purpose of preparing one in the first place.', tag: 'Cash-flow forecasting' },
    { q: 'A business has fixed costs of $8,000 and variable costs of $3 per unit. What are the total costs of producing 1,000 units?', options: ['$11,000', '$8,000', '$3,000', '$24,000'], correct: 0, explain: 'Total costs = fixed costs + (variable cost per unit × output) = $8,000 + ($3 × 1,000) = $8,000 + $3,000 = $11,000.', misconception: 'A common error is forgetting to add the fixed costs, or multiplying fixed costs by output instead of just variable costs.', tag: 'Costs and break-even' },
    { q: 'Which of these best describes a fixed cost?', options: ['A cost that does not change with the level of output, such as rent', 'A cost that rises directly with each extra unit produced', 'A cost that only occurs when output is zero', 'A cost that is always higher than variable costs'], correct: 0, explain: 'Fixed costs, such as rent, salaries and insurance, stay the same regardless of how much a business produces, at least in the short term.', misconception: 'Costs that rise directly with output, such as raw materials, are variable costs, not fixed costs.', tag: 'Costs and break-even' },
    { q: 'A business has revenue of $50,000 and total costs of $42,000. What is its profit or loss?', options: ['$8,000 profit', '$92,000 profit', '$8,000 loss', '$42,000 profit'], correct: 0, explain: 'Profit or loss = revenue − total costs = $50,000 − $42,000 = $8,000 profit.', misconception: 'A common mistake is adding revenue and costs together instead of subtracting costs from revenue.', tag: 'Costs and break-even' },
    { q: 'What does “break-even” mean for a business?', options: ['The level of output or sales at which total revenue exactly equals total costs', 'The point at which a business makes its maximum possible profit', 'The point at which a business has no fixed costs', 'The level of output at which a business must close down'], correct: 0, explain: 'Break-even is the output level at which total revenue equals total costs, so the business makes neither a profit nor a loss.', misconception: 'Break-even is not the point of maximum profit — beyond break-even, a business moves into profit as output and sales increase further.', tag: 'Costs and break-even' },
    { q: 'On a break-even chart, the break-even point is found where:', options: ['The total revenue line crosses the total costs line', 'The fixed cost line meets the horizontal axis', 'Output reaches its maximum capacity', 'The variable cost line is at its highest point'], correct: 0, explain: 'The break-even point on a chart is the point where the total revenue line and total costs line intersect, showing where revenue equals costs.', misconception: 'The break-even point is about where revenue and total costs meet, not simply where a cost line touches an axis or output reaches its maximum.', tag: 'Costs and break-even' },
    { q: 'How would an increase in fixed costs affect the break-even point, all else being equal?', options: ['It would increase the break-even level of output, as more units would need to be sold to cover costs', 'It would decrease the break-even level of output', 'It would have no effect on the break-even point', 'It would automatically increase revenue'], correct: 0, explain: 'An increase in fixed costs raises total costs, meaning a business must sell more units before revenue catches up with costs, raising the break-even point.', misconception: 'Higher fixed costs do not directly increase revenue — they simply raise the sales level needed to cover the higher costs.', tag: 'Costs and break-even' },
    { q: 'What is a limitation of break-even analysis?', options: ['It relies on assumptions, such as constant selling price and costs, which may not hold true in reality', 'It cannot be used by any type of business', 'It always gives a completely accurate prediction of future profit', 'It cannot be shown on a chart'], correct: 0, explain: 'Break-even analysis assumes factors like selling price and costs per unit stay constant, and that everything produced is sold, which is not always realistic.', misconception: 'Break-even analysis is a widely used and chartable tool — its main limitation is the simplifying assumptions it relies on, not that it can’t be used or visualised.', tag: 'Costs and break-even' },
    { q: 'What is the main purpose of a statement of comprehensive income?', options: ['To show a business’s revenue, costs and profit or loss over a trading period', 'To show a business’s assets and liabilities at a single point in time', 'To forecast future cash inflows and outflows', 'To record the personal spending of the business owner'], correct: 0, explain: 'A statement of comprehensive income (income statement) shows a business’s revenue, costs and resulting profit or loss over a given trading period, such as a year.', misconception: 'Assets and liabilities at a point in time are shown on a statement of financial position, not a statement of comprehensive income.', tag: 'Financial documents' },
    { q: 'How is gross profit calculated?', options: ['Sales revenue minus cost of sales', 'Sales revenue minus all business expenses', 'Sales revenue minus fixed costs only', 'Cost of sales minus expenses'], correct: 0, explain: 'Gross profit = sales revenue − cost of sales, showing the profit made from trading before other business expenses are deducted.', misconception: 'Subtracting all expenses gives operating profit, not gross profit — gross profit only deducts the direct cost of the goods sold.', tag: 'Financial documents' },
    { q: 'How is operating profit calculated from gross profit?', options: ['Gross profit minus expenses (overheads)', 'Gross profit plus expenses', 'Sales revenue minus gross profit', 'Cost of sales minus gross profit'], correct: 0, explain: 'Operating profit = gross profit − expenses, such as rent, wages and other overheads, showing the profit made from normal trading operations.', misconception: 'Expenses are subtracted from, not added to, gross profit to reach operating profit.', tag: 'Financial documents' },
    { q: 'What is the main purpose of a statement of financial position?', options: ['To show what a business owns (assets) and owes (liabilities) at a specific point in time', 'To show revenue and costs over a trading period', 'To forecast future sales', 'To calculate a business’s break-even point'], correct: 0, explain: 'A statement of financial position (balance sheet) is a snapshot showing a business’s assets, liabilities and capital at one particular point in time.', misconception: 'Revenue and costs over a period are shown in the statement of comprehensive income, not the statement of financial position.', tag: 'Financial documents' },
    { q: 'Which of these is a current asset?', options: ['Inventory (stock)', 'Machinery expected to be used for many years', 'A long-term bank loan', 'Buildings owned by the business'], correct: 0, explain: 'Current assets are items expected to be turned into cash or used up within a year, such as inventory, trade receivables and cash itself.', misconception: 'Machinery and buildings are non-current (fixed) assets, held for long-term use, and a long-term loan is a liability, not an asset.', tag: 'Financial documents' },
    { q: 'What does “capital employed” mean?', options: ['The total long-term funds invested in a business, from owners and long-term loans', 'The total cash a business has in its bank account today', 'The value of a business’s current liabilities only', 'The revenue earned by a business in a single year'], correct: 0, explain: 'Capital employed is the total long-term finance invested in a business, including share capital and long-term liabilities, used to fund its assets and operations.', misconception: 'Capital employed is a broader, long-term measure of funding, not simply the cash balance or revenue for one year.', tag: 'Financial documents' },
    { q: 'A business has gross profit of $30,000 and sales revenue of $100,000. What is its gross profit margin?', options: ['30%', '3%', '70%', '300%'], correct: 0, explain: 'Gross profit margin = (gross profit ÷ sales revenue) × 100 = ($30,000 ÷ $100,000) × 100 = 30%.', misconception: 'A common error is forgetting to multiply by 100 to express the ratio as a percentage.', tag: 'Accounts analysis' },
    { q: 'What does a rising gross profit margin over time generally suggest?', options: ['The business is becoming more efficient at controlling the cost of the goods it sells relative to its sales', 'The business’s total sales revenue must be falling', 'The business has increased its fixed costs', 'The business is definitely making a net loss'], correct: 0, explain: 'A rising gross profit margin suggests a business is keeping the cost of sales relatively lower compared with its revenue, improving profitability from trading.', misconception: 'A rising gross margin does not require falling revenue, and margin trends alone don’t determine whether a business is in overall loss.', tag: 'Accounts analysis' },
    { q: 'What is the operating profit margin used to assess?', options: ['How much profit a business makes from its normal trading activities as a percentage of sales', 'How much cash a business has available today', 'The value of a business’s non-current assets', 'The break-even level of output'], correct: 0, explain: 'The operating profit margin shows operating profit as a percentage of sales revenue, indicating how efficiently a business turns sales into profit from its core operations.', misconception: 'This ratio is about profitability from operations, not a measure of cash balances, assets, or break-even output.', tag: 'Accounts analysis' },
    { q: 'What does return on capital employed (ROCE) measure?', options: ['How efficiently a business generates profit from the capital invested in it', 'The total number of shares a business has issued', 'The value of a business’s current liabilities', 'The percentage change in sales revenue'], correct: 0, explain: 'ROCE measures how effectively a business uses the long-term capital invested in it to generate operating profit, expressed as a percentage.', misconception: 'ROCE is a profitability-versus-investment measure, not a count of shares or a simple sales growth figure.', tag: 'Accounts analysis' },
    { q: 'A business has current assets of $40,000 and current liabilities of $20,000. What is its current ratio?', options: ['2:1', '1:2', '20:1', '0.5:1'], correct: 0, explain: 'Current ratio = current assets ÷ current liabilities = $40,000 ÷ $20,000 = 2, usually expressed as 2:1.', misconception: 'It is easy to accidentally divide the wrong way round, giving the inverse ratio instead of current assets over current liabilities.', tag: 'Accounts analysis' },
    { q: 'What does the current ratio measure?', options: ['A business’s ability to pay its short-term (current) liabilities using its current assets', 'A business’s long-term profitability', 'The total value of a business’s fixed assets', 'The percentage of sales that are profit'], correct: 0, explain: 'The current ratio is a liquidity measure, showing whether a business has enough current assets to cover its current liabilities.', misconception: 'Liquidity ratios like the current ratio assess short-term financial health, not overall profitability or asset value.', tag: 'Accounts analysis' },
    { q: 'How does the acid test ratio differ from the current ratio?', options: ['The acid test ratio excludes inventory (stock) from current assets, as stock may not be quickly convertible to cash', 'The acid test ratio includes non-current assets', 'The acid test ratio ignores current liabilities entirely', 'There is no difference between the two ratios'], correct: 0, explain: 'The acid test (quick) ratio removes inventory from current assets, giving a stricter measure of liquidity since stock can take time to sell and convert into cash.', misconception: 'The acid test ratio still uses current liabilities in its calculation — the key difference is excluding stock from current assets.', tag: 'Accounts analysis' },
    { q: 'What does “liquidity” mean in a business context?', options: ['A business’s ability to meet its short-term financial obligations using cash or assets easily converted to cash', 'The total long-term profit a business has made', 'The number of products a business sells in liquid form', 'A measure of how much a business owes in total'], correct: 0, explain: 'Liquidity refers to how easily a business can access cash to meet its short-term debts and obligations as they fall due.', misconception: 'Liquidity is specifically about short-term cash access, not total profit or the physical form of the products sold.', tag: 'Accounts analysis' },
    { q: 'Why might a business compare its financial ratios with those of previous years or other businesses?', options: ['To assess whether its performance is improving or how it compares with competitors', 'Because ratios cannot be interpreted on their own in any way', 'Because it is a legal requirement to do so every month', 'To calculate its break-even point'], correct: 0, explain: 'Comparing ratios over time or against competitors helps a business judge whether its performance is improving, declining, or how it stacks up against similar businesses.', misconception: 'While comparison adds useful context, ratios can still offer some insight even alone — and this comparison is not itself a break-even calculation or legal requirement.', tag: 'Accounts analysis' }
  ];

